    settings_text_color_label: "צבע טקסט", settings_font_label: "פונט (פרימיום)", font_picker_default_option: "ברירת מחדל", font_search_placeholder: "חיפוש פונט...", settings_accessibility_label: "נגישות צבעים וניגודיות", settings_high_contrast_label: "מצב ניגודיות גבוהה", settings_color_filter_label: "מסנן צבע", color_filter_none: "ללא", color_filter_grayscale: "גווני אפור",
