    habit_history_stat_current: "Obecna seria", habit_history_stat_best: "Najlepsza seria", habit_history_stat_total: "Łącznie dni", habits_empty_hint: "Nie masz jeszcze żadnych nawyków - dodaj jeden, aby zacząć śledzić swoją serię.", habits_add_modal_title: "Nowy nawyk", habits_name_placeholder: "np. Pić wodę, Czytać, Medytować...", habits_missing_name: "Podaj nazwę nawyku",
