    auth_forgot_password_link: "Has oblidat la contrasenya?", auth_back_to_login: "Torna a l'inici de sessió", auth_forgot_subtitle: "Introdueix el teu correu i t'enviarem un enllaç de restabliment:", auth_forgot_submit_btn: "Envia l'enllaç de restabliment", auth_fill_email: "Introdueix el teu correu", auth_forgot_success: "Si aquest correu existeix, un enllaç de restabliment ja està en camí - revisa la teva safata d'entrada.",
