    auth_forgot_password_link: "Glemt adgangskode?", auth_back_to_login: "Tilbage til login", auth_forgot_subtitle: "Indtast din e-mail, så sender vi dig et link til nulstilling:", auth_forgot_submit_btn: "Send nulstillingslink", auth_fill_email: "Indtast venligst din e-mail", auth_forgot_success: "Hvis den e-mail findes, er et nulstillingslink på vej - tjek din indbakke.",
